import os
import json

# ---- Папки, которые 100% игнорируем ----
EXCLUDE_DIRS = {
    "__pycache__", ".git", "venv", ".venv", "env", ".idea", ".vscode",
    "node_modules", "redis", "postgres", "backup", "cache",
    "htmlcov", "dist", "build", "coverage", ".pytest_cache",
    "chroma_db", "qdrant", "data", "database", "db", "storage",
    "vectorstore", "datasets", "logs", "app/logs",
    ".github",        # <--- добавлено
}


# ---- Разрешённые форматы ----
ALLOWED_EXTS = {".py", ".yml", ".yaml"}

# ---- Dockerfile без расширения ----
ALLOWED_FILENAMES = {"Dockerfile", "dockerfile"}

# ---- Ограничение размера файла ----
MAX_BYTES = 200 * 1024   # 200 KB


def collect_files(root: str):
    dataset = []

    for dirpath, dirnames, filenames in os.walk(root):

        # убираем мусорные директории
        dirnames[:] = [d for d in dirnames if d not in EXCLUDE_DIRS]

        for filename in filenames:
            path = os.path.join(dirpath, filename)
            ext = os.path.splitext(filename)[1].lower()

            # проверяем включение
            include = (
                ext in ALLOWED_EXTS or
                filename in ALLOWED_FILENAMES
            )
            if not include:
                continue

            # ограничение размера
            try:
                if os.path.getsize(path) > MAX_BYTES:
                    continue
            except:
                continue

            # читаем содержимое
            try:
                with open(path, "r", encoding="utf-8", errors="ignore") as f:
                    content = f.read()
            except Exception as e:
                content = f"[READ ERROR: {e}]"

            dataset.append({
                "path": path,
                "name": filename,
                "extension": ext,
                "content": content,
            })

    dataset.sort(key=lambda x: x["path"])
    return dataset


def save_as_json(dataset, out_file="project_fulltext.json"):
    with open(out_file, "w", encoding="utf-8") as f:
        json.dump(dataset, f, ensure_ascii=False, separators=(",", ":"))
    print(f"Saved {len(dataset)} files → {out_file}")


if __name__ == "__main__":
    data = collect_files(".")
    save_as_json(data)

